import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, TorusKnotGeometry, CylinderGeometry, PlaneGeometry,
    DirectionalLight, PointLight, AmbientLight, RepeatWrapping, DoubleSide } = ctx.THREE;

  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primHandles = [];

  const COL = {
    surface: '#14141a',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    g0: '#0b0b10',
    g1: '#101017',
    g2: '#16161d',
  };

  // ---------- Backdrop (vertical gradient) ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const y = uv().y;
    const lower = mix(color(COL.g0), color(COL.g1), smoothstep(0.0, 0.7, y));
    const full = mix(lower, color(COL.g2), smoothstep(0.7, 1.0, y));
    backdropMat.colorNode = full;
    backdropMat.toneMapped = false;
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.2, -3);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- Pedestal ----------
  const pedGeo = new CylinderGeometry(1.1, 1.15, 0.5, 96, 1, false);
  const pedMat = new MeshStandardNodeMaterial();
  pedMat.color = color(COL.surface);
  pedMat.roughness = 0.7;
  pedMat.metalness = 0.35;
  const pedestal = new Mesh(pedGeo, pedMat);
  pedestal.position.set(0, -0.6, 0); // top face at y = -0.35
  group.add(pedestal);
  disposables.push(pedGeo, pedMat);

  // chamfered top ring catching key light
  const chamGeo = new CylinderGeometry(1.11, 1.08, 0.03, 96, 1, false);
  const chamMat = new MeshStandardNodeMaterial();
  chamMat.color = color(COL.paper);
  chamMat.roughness = 0.45;
  chamMat.metalness = 0.5;
  const chamfer = new Mesh(chamGeo, chamMat);
  chamfer.position.set(0, -0.36, 0);
  group.add(chamfer);
  disposables.push(chamGeo, chamMat);

  // ---------- Contact shadow ----------
  const shadowGeo = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.color = color('#000000');
  {
    const d = uv().sub(0.5).length();
    shadowMat.opacityNode = smoothstep(0.5, 0.0, d).mul(0.6);
  }
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  shadowMat.toneMapped = false;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.355, 0);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- Torus knot (material study) ----------
  const knotGroup = new Group();
  knotGroup.position.set(0, 0.4, 0);
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial();
  knotMat.color = color('#cfd4db');
  knotMat.roughness = 0.55;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  if ('anisotropy' in knotMat) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }
  const knot = new Mesh(knotGeo, knotMat);
  knotGroup.add(knot);
  group.add(knotGroup);
  disposables.push(knotGeo, knotMat);

  // brushed-metal roughness map (imperfection / anisotropy read)
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.assets?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.wrapS = RepeatWrapping;
      tex.wrapT = RepeatWrapping;
      tex.repeat.set(2, 2);
      knotMat.roughnessMap = tex;
      knotMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------- Lights (node-local rim + fill) ----------
  const rim = new DirectionalLight(COL.accent, 1.2);
  rim.position.set(-3, 2.4, -2.2);
  group.add(rim);

  const fill = new PointLight(COL.paper, 0.7, 20);
  fill.position.set(2.4, 1.6, 3.2);
  group.add(fill);

  const amb = new AmbientLight(COL.g1, 0.35);
  group.add(amb);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  const PX = 0.006;

  const mk = (str, opts, yUnits) => {
    const t = ctx.fontAtlas.createText(str, opts);
    t.scale.setScalar(PX);
    t.position.set(0, yUnits, 0.05);
    group.add(t);
    textMeshes.push(t);
    return t;
  };

  let placedHeadline = false;
  let placedCaption = false;
  for (const item of items) {
    const role = item.role;
    const str = String(item.text ?? '');
    if (role === 'headline' && !placedHeadline) {
      mk(str, { fontSize: 68, color: COL.paper, align: 'center', letterSpacingPx: -0.005 * 68 }, -1.2);
      placedHeadline = true;
    } else if (role === 'caption' && !placedCaption) {
      mk(str, { fontSize: 18, color: COL.accent, align: 'center', letterSpacingPx: 0.08 * 18 }, -1.6);
      placedCaption = true;
    }
  }
  if (!placedHeadline) mk('Material study 03', { fontSize: 68, color: COL.paper, align: 'center' }, -1.2);
  if (!placedCaption) mk('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', { fontSize: 18, color: COL.accent, align: 'center', letterSpacingPx: 1.44 }, -1.6);

  // ---------- Cinematic primitives ----------
  const primList = config.cinematicPrimitives ?? [];
  for (const p of primList) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const target = p.name === 'orbit' ? knotGroup : group;
      try {
        const h = fn(target, p.params || {});
        if (h) primHandles.push(h);
      } catch (e) { /* ignore */ }
    }
  }

  // ---------- Entrance: weighted-settle ----------
  group.scale.setScalar(1.04);
  const tl = gsap.timeline();
  tl.from(knotGroup.position, { y: 0.8, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  for (let i = 0; i < textMeshes.length; i++) {
    const tm = textMeshes[i];
    const baseY = tm.position.y;
    tl.from(tm.position, { y: baseY - 0.2, duration: 0.5, ease: 'power2.out' }, 0.2 + i * 0.08);
  }
  timelines.push(tl);

  // ---------- Cleanup ----------
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const t of timelines) { try { t.kill(); } catch (e) {} }
    for (const h of primHandles) { try { h.cleanup && h.cleanup(); } catch (e) {} }
    for (const d of disposables) { try { d.dispose && d.dispose(); } catch (e) {} }
    for (const tm of textMeshes) {
      tm.traverse?.((o) => {
        if (o.geometry) { try { o.geometry.dispose(); } catch (e) {} }
        if (o.material) { try { o.material.dispose(); } catch (e) {} }
      });
    }
  };

  return group;
}
